                    GreenSoft   = Color(0.38, 1.00, 0.50, 0.28),
                    GreenDim    = Color(0.03, 0.20, 0.05, 0.96),
            
                    -- Enemy box themes (visible curve box colors from boxesp)
                    BloodRed       = Color(0.84, 0.010, 0.018, 1.00),
