                        DrawInterval = 0.0167,
                        _CanvasScaleX = 1.0,
                        _CanvasScaleY = 1.0,
                        _CanvasOffsetX = 0.0,
                        _CanvasOffsetY = 0.0,
                        _CachedViewportW = 1920,
                        _CachedViewportH = 1080,
                        _CapsuleCache = setmetatable({}, {__mode="k"}),
                        _ProjectionCache = {},
