            -- ====================================================================
            _G.LexusConfig = _G.LexusConfig or {}
            _G.LexusConfig.ModSkin = _G.LexusConfig.ModSkin or false
            _G.LexusConfig.SkinDeadBox = _G.LexusConfig.SkinDeadBox or false
            _G.LexusConfig.SkinAttachment = _G.LexusConfig.SkinAttachment or false
            _G.LexusConfig.KillMessage = _G.LexusConfig.KillMessage or false
            _G.LexusConfig.KillCountUI = _G.LexusConfig.KillCountUI or false
            _G.LexusConfig.ModEmote = _G.LexusConfig.ModEmote or false

            function _G.MagooEnableAllSkins(enable)
                enable = enable and true or false
                _G.LexusConfig = _G.LexusConfig or {}
                _G.LexusConfig.ModSkin = enable
                _G.LexusConfig.SkinDeadBox = enable
                _G.LexusConfig.SkinAttachment = enable
                _G.LexusConfig.KillMessage = enable
                _G.LexusConfig.KillCountUI = enable
                _G.LexusConfig.ModEmote = enable
                if _G.GTLMODConfig then
                    _G.GTLMODConfig.ModSkin = enable
                    _G.GTLMODConfig.KillMessage = enable
                end
                if not enable then
                    -- allow full reinject next time ON
                    _G.AddOutfitLobbyRestored = false
                    _G.AddOutfitUnexpireDone = false
                    pcall(function()
                        if _G.AddOutfitLobbyState then
                            _G.AddOutfitLobbyState.wardrobeRefreshed = false
                        end
                        if LOBBY then LOBBY.wardrobeRefreshed = false end
                    end)
                    print("[MAGOO] All skins OFF")
                    return
                end
                -- Start hooks once
                if _G.MagooStartAddOutfitSkins then pcall(_G.MagooStartAddOutfitSkins) end
                -- Force wardrobe flags so refresh is never skipped
                pcall(function()
                    if LOBBY then LOBBY.wardrobeRefreshed = false end
                    if _G.AddOutfitLobbyState then
                        _G.AddOutfitLobbyState.wardrobeRefreshed = false
                    end
                    _G.AddOutfitLobbyRestored = false
                    _G.AddOutfitUnexpireDone = false
                end)
                local function forceInjectAndRefresh(why)
                    pcall(function()
                        if not _G.AddOutfit then return end
                        local AO = _G.AddOutfit
                        if AO.persistLoadFromDisk then AO.persistLoadFromDisk() end
                        if AO.persistApplyLoaded then AO.persistApplyLoaded() end
                        if AO.injectAll then AO.injectAll() end
                        if AO.injectArmorySkins then AO.injectArmorySkins() end
                        if AO.refreshWardrobe then AO.refreshWardrobe() end
                        if AO.scheduleInjectRefresh then AO.scheduleInjectRefresh() end
                        if AO.reapplyLobbyEquipped then AO.reapplyLobbyEquipped() end
                        if AO.ensureInjectedResources then AO.ensureInjectedResources() end
                        -- silent reinject (no print lag)
                    end)
                end
                forceInjectAndRefresh("enable")
                -- Lobby data may not be ready yet: retry several times
                pcall(function()
                    local tk = require("common.time_ticker")
                    if not (tk and tk.AddTimerOnce) then return end
                    for _, dly in ipairs({1.0, 3.0, 8.0, 15.0}) do
                        tk.AddTimerOnce(dly, function()
                            if not (_G.LexusConfig and _G.LexusConfig.ModSkin) then return end
                            forceInjectAndRefresh("retry-" .. tostring(dly))
                        end)
                    end
                end)
                -- Light skin-safe pass
                pcall(function()
                    local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
                    if pc and pc.HiggsBoson then
                        pc.HiggsBoson.bMHActive = false
                        pc.HiggsBoson.bCallPreReplication = false
                    end
                end)
                print("[MAGOO] All skins ON — keep LOBBY open; wardrobe reinjects automatically")
            end


