local function AutoRestoreLobbySkin()
    -- Lightweight keeper: rare inject, rare UI refresh (no mid-lobby stutter)
    if not (_G.LexusConfig and _G.LexusConfig.ModSkin) then return end
    if _G.AddOutfit and _G.AddOutfit.isInRealMatch and _G.AddOutfit.isInRealMatch() then return end

    pcall(function()
        local inLobby = true
        pcall(function()
            if GameStatus and GameStatus.IsInLobbyOrMainCity then
                inLobby = GameStatus.IsInLobbyOrMainCity() and true or false
            end
        end)
        if not inLobby then return end

        local AO = _G.AddOutfit
        if not AO then return end

        _G._MagooLobbyKeepN = (_G._MagooLobbyKeepN or 0) + 1
        local n = _G._MagooLobbyKeepN

        -- Heavy inject only every 4th tick (~32s at 8s interval) OR first 2 ticks
        if n <= 2 or (n % 4) == 0 then
            if AO.injectAll then pcall(AO.injectAll) end
            if AO.injectArmorySkins then pcall(AO.injectArmorySkins) end
        end

        -- Wardrobe UI refresh every other tick
        if (n % 2) == 0 then
            pcall(function()
                local LOBBY = _G.AddOutfitLobbyState
                if LOBBY then LOBBY.wardrobeRefreshed = false end
                if AO.refreshWardrobe then AO.refreshWardrobe() end
            end)
        end

        -- Light reapply only (no disk IO every tick)
        if AO.reapplyLobbyEquipped then pcall(AO.reapplyLobbyEquipped) end
        -- Disk load rare
        if (n % 6) == 1 then
            if AO.persistLoadFromDisk then pcall(AO.persistLoadFromDisk) end
            if AO.persistApplyLoaded then pcall(AO.persistApplyLoaded) end
        end
    end)
end

