            if not entity or not entity.bInit then return end
            -- if inject maps look empty / too thin, reinject
            local n = 0
            if AO.resToIns then
                for _ in pairs(AO.resToIns) do n = n + 1 end
            end
            -- R.resToIns is internal; try injectAll always lightly every cycle when lobby
            if AO.injectAll then AO.injectAll() end
            if AO.refreshWardrobe and (n < 20) then AO.refreshWardrobe() end
        end)
    end, -1, 12.0)
end)


