local function DrawToggle(parent, x, y, configKey)
    -- iOS-style pill switch
    local tw, th, tr = 46, 26, 13
    local on = _G.GTLMODConfig[configKey] and true or false
    local trackColor = on and C.ToggleOn or C.ToggleOff
    RoundedPanel(parent, x, y, tw, th, tr, trackColor, 12)
    -- soft inner track edge
    local kw, kh, kr = 20, 20, 10
    local knobX = on and (x + 24) or (x + 3)
    RoundedPanel(parent, knobX, y + 3, kw, kh, kr, C.KnobWhite, 14)
    -- slight shadow under knob
    RoundedPanel(parent, knobX + 1, y + 4, kw, kh, kr, FLinearColor(0, 0, 0, 0.12), 13)
    MakeBtn(parent, x - 6, y - 6, tw + 12, th + 12, 16, function()
        local newState = not (_G.GTLMODConfig[configKey] and true or false)
        UpdateFeature(configKey, newState)
        RenderContent()
    end)
end

local function DrawRow(parent, labelText, yPos, configKey)
    Text(parent, labelText, 119, yPos + 12, 13, C.TextDark, 12, 0.0, 0.5)
    DrawToggle(parent, 570, yPos, configKey)
end

